mkdir -p /tmp/sv-98cf7590b60e43418098fb4eb38abf98/typed-metadata && cd /tmp/sv-98cf7590b60e43418098fb4eb38abf98/typed-metadata && dotnet new console --framework net11.0 -n Demo --force -o . > /dev/null 2>&1 && cat > Program.cs << 'EOF'
using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed metadata retrieval: GetTypeInfo<T>()
//    Returns JsonTypeInfo<T> directly — no cast needed.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Type: {personInfo.Type.Name}");
Console.WriteLine($"Kind: {personInfo.Kind}");
Console.WriteLine($"Properties: {string.Join(", ", personInfo.Properties.Select(p => p.Name))}");

// 2) Probe without throwing: TryGetTypeInfo(Type, out JsonTypeInfo?)
//    Returns false instead of throwing when metadata isn't available.
var limitedOptions = new JsonSerializerOptions
{
    // Resolver that only knows about 'Person' via a source-gen context
    TypeInfoResolver = PersonContext.Default
};

bool hasPerson = limitedOptions.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info);
bool hasOrder  = limitedOptions.TryGetTypeInfo(typeof(Order), out _);

Console.WriteLine($"\nTryGetTypeInfo(Person): {hasPerson} → {info?.Type.Name}");
Console.WriteLine($"TryGetTypeInfo(Order):  {hasOrder} (no exception thrown)");

// Types used in the demo
public record Person(string Name, int Age);
public record Order(int Id, decimal Total);

// Source-generated context that only handles Person
[JsonSerializable(typeof(Person))]
public partial class PersonContext : JsonSerializerContext;
EOF
